Description  The batch inference for a BERT model (Hugging Face implementation) is incorrect in Release 21.09 except for the first sample (without any error message). The wrong results are random-like values (with same order of magnitude). I found some related issues 1 2 3 #842 and some are then reported as fixed without a clear conclusion. This issue state that TensorRT 7.2 fix it. So I try with Release 21.06 and it solve my problem! I'm not sure if this is due to some bug in my code, so I pasted a reproducible code snippet below. Additionally, I found that it works well when I replace BERT to a single fully-connected network. (see the TODO comment block) Environment Release 21.06 and Release 21.09 TensorRT Version: NVIDIA GPU: P100 NVIDIA Driver Version: 470.57.02 CUDA Version: 11.4 CUDNN Version: Operating System: Ubuntu 20.04 Python Version (if applicable): Tensorflow Version (if applicable): PyTorch Version (if applicable): Baremetal or Container (if so, version): Steps To Reproduce  Codes # trt_utils.py import os  import tensorrt as trt import pycuda.driver as cuda import numpy as np import pycuda.autoinit   TRT_LOGGER = trt.Logger(trt.Logger.WARNING)  def build_engine(onnx_file_path, input_shape, max_batch_size):     with trt.Builder(TRT_LOGGER) as builder, builder.create_network(1 << int(trt.NetworkDefinitionCreationFlag.EXPLICIT_BATCH)) as network, trt.OnnxParser(network, TRT_LOGGER) as parser:         builder.max_batch_size = max_batch_size          config = builder.create_builder_config()         config.max_workspace_size = (1 << 32)         profile = builder.create_optimization_profile()          with open(onnx_file_path, 'rb') as model:             parsing_succeed = parser.parse(model.read())             assert parsing_succeed, 'Failed to parse the ONNX model'          profile.set_shape('input', (2,) + input_shape, (2,) +                           input_shape, (max_batch_size,) + input_shape)         config.add_optimization_profile(profile)          engine = builder.build_engine(network, config=config)         assert engine, 'Failed to build the engine'     return engine   class HostDeviceMem(object):     def __init__(self, host_mem, device_mem):         self.host = host_mem         self.device = device_mem      def __str__(self):         return "Host:
" + str(self.host) + "
Device:
" + str(self.device)      def __repr__(self):         return self.__str__()   def allocate_buffers(engine):     inputs = []     outputs = []     bindings = []     stream = cuda.Stream()     for binding in engine:         size = trt.volume(engine.get_binding_shape(             binding)[1:]) * engine.max_batch_size         dtype = trt.nptype(engine.get_binding_dtype(binding))         binding_index = engine.get_binding_index(binding)          # Allocate host and device buffers         host_mem = cuda.pagelocked_empty(size, dtype)         # Only bytes, no need for size         device_mem = cuda.mem_alloc(host_mem.nbytes)          # Append the device buffer to device bindings.         bindings.append(int(device_mem))          # Append to the appropriate list.         if engine.binding_is_input(binding):             inputs.append(HostDeviceMem(host_mem, device_mem))         else:             outputs.append(HostDeviceMem(host_mem, device_mem))     return inputs, outputs, bindings, stream # test.py import numpy as np import pycuda.driver as cuda import torch import torch.nn as nn import onnxruntime from transformers import BertConfig, BertModel  from trt_utils import allocate_buffers, build_engine   VEC_LEN = 512 BATCH_SIZE = 2 MAX_BATCH_SIZE = 32   class Net(nn.Module):      def __init__(self):         super(Net, self).__init__()         self.fc = nn.Linear(VEC_LEN, VEC_LEN)      def forward(self, x):         y = self.fc(x)         return y, x   def assert_equality(pytorch_output, np_output, method=''):      def extract_pytorch_output(tensor):         return [             tensor.last_hidden_state.numpy(),             tensor.pooler_output.numpy(),         ]      def correct_rate(pytorch_output, np_output):         def do_correct_rate(arr1, arr2):             correct = np.isclose(                 arr1.flatten(), arr2.flatten(), atol=1e-05).sum()             total = arr1.flatten().size             return f'{correct}/{total}'         return [             do_correct_rate(arr1, arr2)             for arr1, arr2 in zip(extract_pytorch_output(pytorch_output), np_output)         ]      assert all(         np.allclose(arr1.flatten(), arr2.flatten(), atol=1e-05)         for arr1, arr2 in zip(extract_pytorch_output(pytorch_output), np_output)     ), (f"Output of {method} and PyTorch doesn't match.
"         f"Correct rate: {correct_rate(pytorch_output, np_output)}
"         f"{pytorch_output=}
"         f"{np_output=}
")   def test():      model = BertModel(BertConfig())     input_ids = torch.randint(30522, (BATCH_SIZE, VEC_LEN), dtype=torch.long)      # TODO: Uncomment this block to try simple fc net     # model = Net()     # input_ids = torch.rand((BATCH_SIZE, VEC_LEN))      model.eval()      with torch.no_grad():         pytorch_output = model(input_ids)      # ONNX     onnx_model_path = 'net.onnx'     torch.onnx.export(model, input_ids, onnx_model_path, export_params=True,                       opset_version=13, verbose=False, input_names=['input'],                       output_names=['output1', 'output2'],                       dynamic_axes={'input': {0: 'batch_size'},                                     'output1': {0: 'batch_size'},                                     'output2': {0: 'batch_size'}},                       )      ort_session = onnxruntime.InferenceSession(onnx_model_path)     onnx_output = ort_session.run(         None, {ort_session.get_inputs()[0].name: input_ids.numpy()})      assert_equality(pytorch_output, onnx_output, 'ONNXRuntime')     print('ONNX Good!')      # TensorRT     engine = build_engine(onnx_model_path,                           input_ids.size()[1:],                           max_batch_size=MAX_BATCH_SIZE)      context = engine.create_execution_context()     context.set_binding_shape(0, input_ids.size())      inputs, outputs, bindings, stream = allocate_buffers(engine)     inputs[0].host[:input_ids.nelement()] = np.asarray(input_ids).ravel()      [cuda.memcpy_htod(inp.device, inp.host) for inp in inputs]     success = context.execute_v2(bindings=bindings)     print(f'TensorRT exec {success=}')     [cuda.memcpy_dtoh(out.host, out.device) for out in outputs]      trt_output = [         out.host.reshape(MAX_BATCH_SIZE, -1)[:BATCH_SIZE]         for out in outputs     ]      assert_equality(pytorch_output, trt_output, 'TensorRT')     print('TensorRT Good!')   test() Run python3 test.py  Output of Release 21.06 /usr/local/lib/python3.8/dist-packages/onnxruntime/capi/onnxruntime_inference_collection.py:350: UserWarning: Deprecation warning. This ORT build has ['CUDAExecutionProvider', 'CPUExecutionProvider'] enabled. The next release (ORT 1.10) will require explicitly setting the providers parameter (as opposed to the current behavior of providers getting set/registered by default based on the build flags) when instantiating InferenceSession.For example, onnxruntime.InferenceSession(..., providers=["CUDAExecutionProvider"], ...)   warnings.warn("Deprecation warning. This ORT build has {} enabled. ".format(available_providers) + ONNX Good! [TensorRT] WARNING: /home/jenkins/agent/workspace/OSS/OSS_L0_MergeRequest/oss/parsers/onnx/onnx2trt_utils.cpp:271: Your ONNX model has been generated with INT64 weights, while TensorRT does not natively support INT64. Attempting to cast down to INT32. [TensorRT] WARNING: Output type must be INT32 for shape outputs TensorRT exec success=True TensorRT Good!  Output of Release 21.09 /usr/local/lib/python3.8/dist-packages/onnxruntime/capi/onnxruntime_inference_collection.py:350: UserWarning: Deprecation warning. This ORT build has ['CUDAExecutionProvider', 'CPUExecutionProvider'] enabled. The next release (ORT 1.10) will require explicitly setting the providers parameter (as opposed to the current behavior of providers getting set/registered by default based on the build flags) when instantiating InferenceSession.For example, onnxruntime.InferenceSession(..., providers=["CUDAExecutionProvider"], ...)   warnings.warn("Deprecation warning. This ORT build has {} enabled. ".format(available_providers) + ONNX Good! [TensorRT] WARNING: onnx2trt_utils.cpp:362: Your ONNX model has been generated with INT64 weights, while TensorRT does not natively support INT64. Attempting to cast down to INT32. [TensorRT] WARNING: Output type must be INT32 for shape outputs [TensorRT] WARNING: Detected invalid timing cache, setup a local cache instead TensorRT exec success=True Traceback (most recent call last):   File "bert_snippet.py", line 111, in <module>     test()   File "bert_snippet.py", line 107, in test     assert_equality(pytorch_output, trt_output, 'TensorRT')   File "bert_snippet.py", line 46, in assert_equality     assert all( AssertionError: Output of TensorRT and PyTorch doesn't match. Correct rate: ['393222/786432', '768/1536'] pytorch_output=BaseModelOutputWithPoolingAndCrossAttentions(last_hidden_state=tensor([[[ 0.0546,  0.2669,  0.8374,  ..., -0.7832, -0.5110, -0.9227],          [-0.1837, -0.3121, -0.2003,  ..., -0.7889,  0.2879, -0.0161],          [ 0.2569, -0.9711,  1.9910,  ...,  0.0300, -1.0024, -0.6459],          ...,          [ 1.1023,  0.0119,  1.8955,  ...,  0.0562, -0.2778,  0.7635],          [-0.1440, -0.5040,  0.9521,  ...,  1.1965,  0.1977, -0.7471],          [-0.5223, -1.4304, -0.0173,  ...,  0.2297, -0.4449, -0.2978]],          [[ 0.6351, -0.1982, -0.2601,  ...,  0.4886,  0.0689,  0.7333],          [-1.1930, -0.3422,  1.1272,  ...,  0.4254, -0.2549, -0.1675],          [ 1.2090, -0.4521,  1.7832,  ..., -0.4979, -0.5859, -0.1861],          ...,          [ 1.1340, -0.3403,  2.0484,  ...,  0.1718, -0.0468, -0.4998],          [ 0.5129, -0.6067,  1.0069,  ...,  0.4663, -0.7445,  0.6771],          [ 0.0607, -1.0137,  1.8691,  ...,  0.2961,  0.1203,  0.4264]]]), pooler_output=tensor([[-0.1826,  0.0255, -0.2046,  ...,  0.2922,  0.8912,  0.3630],         [-0.1114,  0.0243, -0.6291,  ...,  0.2883,  0.8470,  0.5640]]), hidden_states=None, past_key_values=None, attentions=None, cross_attentions=None) np_output=[array([[ 0.05455616,  0.26694223,  0.8373928 , ...,  0.22968616,         -0.4449291 , -0.29782966],        [ 0.52241874, -0.3795954 ,  0.44035733, ..., -0.81233   ,         -0.27850032,  0.01815133]], dtype=float32), array([[-0.18258236,  0.02551227, -0.20462437, ...,  0.2921529 ,          0.891194  ,  0.36304623],        [-0.37625638,  0.14089146, -0.61692894, ...,  0.28234258,          0.63531446,  0.2062083 ]], dtype=float32)

Description stream is always blocking in my compute,another is not. i try in different computer, only my computer is not. code #include  #include  #include  #include <cuda.h> #include "cuda_runtime.h" #include "device_launch_parameters.h" #include <stdio.h> cudaError_t addWithCuda(int *c, const int *a, const int *b, unsigned int size); global void addKernel(int *c, const int *a, const int *b) { int i = threadIdx.x; c[i] = a[i] + b[i]; } const int N = 1 << 20; global void kernel(float *x, int n) { int tid = threadIdx.x + blockIdx.x * blockDim.x; for (int i = tid; i < n; i += blockDim.x * gridDim.x) { x[i] = sqrt(pow(3.14159, i)); } } global void convertPixelFormat(uint8_t* inputBgra, uint8_t* outputYuv, int numPixels) { for(int k = 0;k<100;k++) { int stride = gridDim.x * blockDim.x; int idx = threadIdx.x + blockIdx.x * blockDim.x; short3 yuv16; char3 yuv8; 	while (idx <= numPixels) { 		if (idx < numPixels) { 			yuv16.x = 66 * inputBgra[idx * 4 + 2] + 129 * inputBgra[idx * 4 + 1] + 25 * inputBgra[idx * 4]; 			yuv16.y = -38 * inputBgra[idx * 4 + 2] + -74 * inputBgra[idx * 4 + 1] + 112 * inputBgra[idx * 4]; 			yuv16.z = 112 * inputBgra[idx * 4 + 2] + -94 * inputBgra[idx * 4 + 1] + -18 * inputBgra[idx * 4];  			yuv8.x = (yuv16.x >> 8) + 16; 			yuv8.y = (yuv16.y >> 8) + 128; 			yuv8.z = (yuv16.z >> 8) + 128;  			*(reinterpret_cast<char3*>(&outputYuv[idx * 3])) = yuv8; 		} 		idx += stride; 	} }  } int main() { uint8_t* bgraBuffer; uint8_t* yuvBuffer; uint8_t* deviceBgraBuffer; uint8_t* deviceYuvBuffer; const int dataSizeBgra = 7680 * 4320 * 4; const int dataSizeYuv = 7680 * 4320 * 3;  cudaMallocHost(&bgraBuffer, dataSizeBgra); cudaMallocHost(&yuvBuffer, dataSizeYuv); cudaMalloc(&deviceBgraBuffer, dataSizeBgra); cudaMalloc(&deviceYuvBuffer, dataSizeYuv);  const int nStreams = 4;  std::cout << " " << std::endl; std::cout << "Computing results using GPU, using " << nStreams << " streams." << std::endl; std::cout << " " << std::endl;  cudaStream_t streams[nStreams]; std::cout << "    Creating " << nStreams << " CUDA streams." << std::endl; for (int i = 0; i < nStreams; i++) { 	cudaStreamCreate(&streams[i]); }  int brgaOffset = 0; int yuvOffset = 0; const int brgaChunkSize = dataSizeBgra / nStreams; const int yuvChunkSize = dataSizeYuv / nStreams;  for (int i = 0; i < nStreams; i++) { 	std::cout << "        Launching stream " << i << "." << std::endl; 	brgaOffset = brgaChunkSize * i; 	yuvOffset = yuvChunkSize * i; 	cudaMemcpyAsync(deviceBgraBuffer + brgaOffset, 		bgraBuffer + brgaOffset, 		brgaChunkSize, 		cudaMemcpyHostToDevice, 		streams[i]);  	convertPixelFormat << <4096, 1024, 0, streams[i] >> > (deviceBgraBuffer + brgaOffset, deviceYuvBuffer + yuvOffset, brgaChunkSize / 4);  	cudaMemcpyAsync(yuvBuffer + yuvOffset, 		deviceYuvBuffer + yuvOffset, 		yuvChunkSize, 		cudaMemcpyDeviceToHost, 		streams[i]); }  //for (int i = 0; i < nStreams; i++) {  //	cudaStreamSynchronize(streams[i]);  //} cudaDeviceSynchronize();  for (int i = 0; i < nStreams; i++) { 	cudaStreamDestroy(streams[i]); } //const int arraySize = 5; //const int a[arraySize] = { 1, 2, 3, 4, 5 }; //const int b[arraySize] = { 10, 20, 30, 40, 50 }; //int c[arraySize] = { 0 };  //// Add vectors in parallel. //cudaError_t cudaStatus = addWithCuda(c, a, b, arraySize); //if (cudaStatus != cudaSuccess) { //    fprintf(stderr, "addWithCuda failed!"); //    return 1; //}  //printf("{1,2,3,4,5} + {10,20,30,40,50} = {%d,%d,%d,%d,%d}
", //    c[0], c[1], c[2], c[3], c[4]);  //// cudaDeviceReset must be called before exiting in order for profiling and //// tracing tools such as Nsight and Visual Profiler to show complete traces. //cudaStatus = cudaDeviceReset(); //if (cudaStatus != cudaSuccess) { //    fprintf(stderr, "cudaDeviceReset failed!"); //    return 1; //} return 0;  } // Helper function for using CUDA to add vectors in parallel. cudaError_t addWithCuda(int *c, const int *a, const int *b, unsigned int size) { int *dev_a = 0; int *dev_b = 0; int *dev_c = 0; cudaError_t cudaStatus; // Choose which GPU to run on, change this on a multi-GPU system. cudaStatus = cudaSetDevice(0); if (cudaStatus != cudaSuccess) {     fprintf(stderr, "cudaSetDevice failed!  Do you have a CUDA-capable GPU installed?");     goto Error; }  // Allocate GPU buffers for three vectors (two input, one output)    . cudaStatus = cudaMalloc((void**)&dev_c, size * sizeof(int)); if (cudaStatus != cudaSuccess) {     fprintf(stderr, "cudaMalloc failed!");     goto Error; }  cudaStatus = cudaMalloc((void**)&dev_a, size * sizeof(int)); if (cudaStatus != cudaSuccess) {     fprintf(stderr, "cudaMalloc failed!");     goto Error; }  cudaStatus = cudaMalloc((void**)&dev_b, size * sizeof(int)); if (cudaStatus != cudaSuccess) {     fprintf(stderr, "cudaMalloc failed!");     goto Error; }  // Copy input vectors from host memory to GPU buffers. cudaStatus = cudaMemcpy(dev_a, a, size * sizeof(int), cudaMemcpyHostToDevice); if (cudaStatus != cudaSuccess) {     fprintf(stderr, "cudaMemcpy failed!");     goto Error; }  cudaStatus = cudaMemcpy(dev_b, b, size * sizeof(int), cudaMemcpyHostToDevice); if (cudaStatus != cudaSuccess) {     fprintf(stderr, "cudaMemcpy failed!");     goto Error; }  // Launch a kernel on the GPU with one thread for each element. addKernel<<<1, size>>>(dev_c, dev_a, dev_b);  // Check for any errors launching the kernel cudaStatus = cudaGetLastError(); if (cudaStatus != cudaSuccess) {     fprintf(stderr, "addKernel launch failed: %s
", cudaGetErrorString(cudaStatus));     goto Error; }  // cudaDeviceSynchronize waits for the kernel to finish, and returns // any errors encountered during the launch. cudaStatus = cudaDeviceSynchronize(); if (cudaStatus != cudaSuccess) {     fprintf(stderr, "cudaDeviceSynchronize returned error code %d after launching addKernel!
", cudaStatus);     goto Error; }  // Copy output vector from GPU buffer to host memory. cudaStatus = cudaMemcpy(c, dev_c, size * sizeof(int), cudaMemcpyDeviceToHost); if (cudaStatus != cudaSuccess) {     fprintf(stderr, "cudaMemcpy failed!");     goto Error; }  Error: cudaFree(dev_c); cudaFree(dev_a); cudaFree(dev_b); return cudaStatus;  }

