nd.cudaMemcpyDeviceToHost     [         cuda_call(             cudart.cudaMemcpyAsync(out.host, out.device, out.nbytes, kind, stream)         )         for out in outputs     ]     cuda_call(cudart.cudaStreamSynchronize(stream))     return [out.host for out in outputs]   def do_inference_v2(context, bindings, inputs, outputs, stream):     def execute_async():         context.execute_async_v2(bindings=bindings, stream_handle=stream)      return _do_inference_base(inputs, outputs, stream, execute_async)  first model inference: # Allocate buffers based on input shape         input_name = self.engine.get_tensor_name(0)         self.context.set_input_shape(input_name, input0.shape)          model_shapes = [input0.shape, output0.shape, output1.shape]         self.inputs, self.outputs, self.bindings, self.stream = common.allocate_buffers(self.engine, model_shapes)          # Run inference on input         np.copyto(self.inputs[0].host, input0.ravel())         out = common.do_inference_v3(self.context, self.engine, self.bindings, self.inputs, self.outputs, self.stream)         out0 = torch.from_numpy(out[0].reshape(output0.shape).clone()         out1 = torch.from_numpy(out[1].reshape(output1.shape).clone()         #out0 = torch.from_numpy(self.outputs[0].host.reshape(output0.shape).copy())         #out1 = torch.from_numpy(self.outputs[1].host.reshape(output1.shape).copy())         common.free_buffers(self.inputs, self.outputs, self.stream)  second model inference:         model_shapes = [             input0.shape,             input1.shape,             input2.shape,             input3.shape,             input4.shape,             input5.shape,             output0.shape,         ]         # Set binding for context base on the input shape         input_binding_index = self.engine.get_tensor_name(0)         self.context.set_input_shape(input_binding_index, input0.shape)         input_binding_index = self.engine.get_tensor_name(1)         self.context.set_input_shape(input_binding_index, input1.shape)         input_binding_index = self.engine.get_tensor_name(2)         self.context.set_input_shape(input_binding_index, input2.shape)         input_binding_index = self.engine.get_tensor_name(3)         self.context.set_input_shape(input_binding_index, input3.shape)         input_binding_index = self.engine.get_tensor_name(4)         self.context.set_input_shape(input_binding_index, input4.shape)         input_binding_index = self.engine.get_tensor_name(5)         self.context.set_input_shape(input_binding_index, input5.shape)         self.inputs, self.outputs, self.bindings, self.stream = common.allocate_buffers(             self.engine, model_shapes         )                  # Transfer data to Host memory         np.copyto(self.inputs[0].host, input0.ravel())         np.copyto(self.inputs[1].host, input1.ravel())         np.copyto(self.inputs[2].host, input2.ravel())         np.copyto(self.inputs[3].host, input3.ravel())         np.copyto(self.inputs[4].host, input4.ravel())         np.copyto(self.inputs[5].host, input5.ravel())          # Do inference         output = common.do_inference_v3(             self.context, self.engine, self.bindings, self.inputs, self.outputs, self.stream         )         # Post proccess the output of model         out0 = torch.from_numpy(             self.outputs[0]             .host.reshape(output0.shape)             .copy()         )         #out0 = torch.from_numpy(output[0].reshape(output0.shape).clone()         common.free_buffers(self.inputs, self.outputs, self.stream)
